#!/bin/sh
tool_config_file(){ case $1 in curl) echo "$CURRENT_HOME/.curlrc";; wget) echo "$CURRENT_HOME/.wgetrc";; ripgrep) echo "$CURRENT_HOME/.ripgreprc";; fd) echo "$CURRENT_HOME/.config/fd/ignore";; fzf) echo "$CURRENT_HOME/.config/fzf/options";; npm) echo "$CURRENT_HOME/.npmrc";; pip) echo "$CURRENT_HOME/.config/pip/pip.conf";; cargo) echo "$CURRENT_HOME/.cargo/config.toml";; make) echo "$CURRENT_HOME/.config/make/make.conf";; git) echo "$CURRENT_HOME/.gitconfig";; tmux) echo "$CURRENT_HOME/.tmux.conf";; screen) echo "$CURRENT_HOME/.screenrc";; htop) echo "$CURRENT_HOME/.config/htop/htoprc";; btop) echo "$CURRENT_HOME/.config/btop/btop.conf";; esac; }
tool_default_body(){ case $1 in curl) printf '%s\n' 'location' 'fail' 'show-error' 'connect-timeout = 20' 'retry = 3';; wget) printf '%s\n' 'timeout = 20' 'tries = 3' 'continue = on' 'timestamping = on';; ripgrep) printf '%s\n' '--smart-case' '--hidden' '--glob=!.git/*' '--line-number';; fzf) printf '%s\n' '--height=60%' '--layout=reverse' '--border' '--info=inline';; npm) printf '%s\n' 'fund=false' 'audit=true' 'update-notifier=false';; pip) printf '%s\n' '[global]' 'timeout = 30' 'disable-pip-version-check = true' '[install]' 'compile = true';; cargo) printf '%s\n' '[net]' 'retry = 3' 'git-fetch-with-cli = true' '[build]' 'jobs = 2';; make) printf '%s\n' 'MAKEFLAGS=-j2 --output-sync=target';; screen) printf '%s\n' 'startup_message off' 'defscrollback 10000' 'term screen-256color';; esac; }
tool_config_generate(){ t=$1; f=$(tool_config_file "$t"); [ -n "$f" ] || return; b=$(tool_default_body "$t"); [ -n "$b" ] || { ui_msg Tools 'No generated preset exists; use the raw editor.'; return; }; write_file "$f" 644 "$b"; }
tool_config_menu(){ while :; do t=$(ui_menu 'Additional tool configuration' 'Generate defaults or edit common tool files.' curl 'curl (.curlrc)' wget 'wget (.wgetrc)' ripgrep 'ripgrep (.ripgreprc)' fd 'fd ignore rules' fzf 'fzf options' npm 'npm (.npmrc)' pip 'pip (pip.conf)' cargo 'Cargo config' make 'Make defaults' git 'Git config' tmux 'Tmux config' screen 'GNU Screen' htop 'htop' btop 'btop') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; a=$(ui_menu "$t" "File: $(tool_config_file "$t")" generate 'Generate recommended defaults' edit 'Open raw configuration' view 'View current configuration' plugins 'Open plugin manager for this tool') || continue; f=$(tool_config_file "$t"); case $a in generate) tool_config_generate "$t";; edit) edit_file "$f";; view) ui_text "$t" "$(cat "$f" 2>/dev/null || echo Missing)";; plugins) plugin_manager_menu "$t";; esac; done; }
project_settings_menu(){ while :; do c=$(ui_menu 'Project settings' "Verbose=$VERBOSE Debug=$DEBUG Dry-run=$DRY_RUN Progress=${PROGRESS_ENABLED:-yes}" verbose 'Toggle verbose command output' progress 'Toggle progress gauges and spinners' debug 'Toggle debug logging' dryrun 'Toggle dry-run command previews' log 'View project log' clear 'Clear project log') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in verbose) [ "$VERBOSE" = yes ] && VERBOSE=no || VERBOSE=yes;; progress) [ "${PROGRESS_ENABLED:-yes}" = yes ] && PROGRESS_ENABLED=no || PROGRESS_ENABLED=yes;; debug) [ "$DEBUG" = yes ] && DEBUG=no || DEBUG=yes;; dryrun) [ "$DRY_RUN" = yes ] && DRY_RUN=no || DRY_RUN=yes;; log) ui_text Log "$(tail -n 500 "$LOG_FILE" 2>/dev/null)";; clear) : >"$LOG_FILE";; esac; settings_save; export VERBOSE DEBUG DRY_RUN PROGRESS_ENABLED; done; }
